SELECT SUM(amount_transfer) AS total_transfer_amount
FROM transaction
WHERE MONTH(trans_time) = 1  GROUP BY amount_transfer, total_transfer_amount ;

SELECT SUM(amount_transfer) AS total_amount
FROM transaction
WHERE trans_time >= DATE_SUB(CURRENT_DATE, INTERVAL 7 DAY) AND amount_transfer > 2000000  GROUP BY amount_transfer, total_amount ;
